import type { Player } from "@/lib/types";
import type { SeasonPhase, SocialPostTopic } from "@/lib/data/socialMediaPosts";

export type SocialPlatform = "x" | "reddit" | "instagram";
export type EligibilityRule = string | ((player: Player) => boolean);
export interface SocialCommentTemplate {
  id: string;
  platforms: SocialPlatform[];
  phases: SeasonPhase[];
  topic: SocialPostTopic;
  tag: string;
  eligibility: string;
  requirements: string[];
  text: string;
  tone: string;
  eligible: EligibilityRule;
  maxPrice?: number;
  minPrice?: number;
}

const auction = (input: Omit<SocialCommentTemplate, "phases" | "topic" | "tag" | "requirements"> & { maxPrice?: number; minPrice?: number }) => ({
  ...input,
  phases: ["post_auction"] as SeasonPhase[],
  topic: "price_tag" as SocialPostTopic,
  tag: "team_bargains",
  requirements: ["bought in current auction", ...(input.maxPrice === undefined ? [] : [`price <= ${input.maxPrice} lakhs`]), ...(input.minPrice === undefined ? [] : [`price >= ${input.minPrice} lakhs`])],
});

const premiumAuction = (input: Omit<SocialCommentTemplate, "phases" | "topic" | "tag" | "requirements"> & { minPrice: number }) => ({
  ...input,
  phases: ["post_auction"] as SeasonPhase[],
  topic: "price_tag" as SocialPostTopic,
  tag: "team_needs",
  requirements: ["bought in current auction", `price >= ${input.minPrice} lakhs`],
});

/** Common plain-language eligibility rules accepted from future comment batches. */
export function matchesEligibility(player: Player, rule: EligibilityRule): boolean {
  if (typeof rule === "function") return rule(player);
  const text = rule.toLowerCase().trim();
  const rating = Math.max(player.currentBatting, player.currentBowling);
  const isBowler = player.role === "Pace Bowler" || player.role === "Spin Bowler" || (player.role === "All-Rounder" && player.currentBowling > player.currentBatting);
  const isBatter = player.currentBatting >= player.currentBowling;
  if (/rating\s*>=\s*(\d+)/.test(text)) return rating >= Number(text.match(/rating\s*>=\s*(\d+)/)?.[1]);
  if (/rating\s*<=\s*(\d+)/.test(text)) return rating <= Number(text.match(/rating\s*<=\s*(\d+)/)?.[1]);
  if (/age\s*<\s*(\d+)/.test(text)) return player.age < Number(text.match(/age\s*<\s*(\d+)/)?.[1]);
  if (/age\s*>=\s*(\d+)/.test(text)) return player.age >= Number(text.match(/age\s*>=\s*(\d+)/)?.[1]);
  if (text.includes("captain material")) return (player.captaincy ?? 0) >= 75;
  if (text.includes("all-rounder")) return player.role === "All-Rounder";
  if (text.includes("primary bowler") || text.includes("pace bowler") || text.includes("spin bowler")) return isBowler && (!text.includes("spin") || player.role === "Spin Bowler") && (!text.includes("pace") || player.role === "Pace Bowler");
  if (text.includes("primary batter") || text.includes("batter")) return isBatter;
  if (text.includes("overseas")) return player.nationality === "Overseas";
  if (text.includes("wicketkeeper") || text.includes("keeper")) return Boolean(player.isWicketkeeper) || player.role === "WK-Batsman";
  if (text.includes("veteran")) return player.age >= 32;
  if (text.includes("former team players")) return (player.iplHistory ?? []).some((entry) => entry.teamId !== player.currentTeamId && entry.teamId !== "");
  if (text === "any" || text === "all players") return true;
  return true;
}

